// Transformar y guardar clientes de Supabase (PARTE 2)
const staticData = $getWorkflowStaticData('global');
const clientes = [];

for (const item of $input.all()) {
  const c = item.json;

  // Solo procesar si tiene teléfono válido
  if (!c.phone || c.phone.trim() === '') continue;

  // Normalizar teléfono (remover caracteres no numéricos)
  let telefonoNormalizado = c.phone.replace(/[^0-9]/g, '');

  // Asegurar prefijo 57 si es número colombiano (10 dígitos)
  if (telefonoNormalizado.length === 10 && telefonoNormalizado.startsWith('3')) {
      telefonoNormalizado = '57' + telefonoNormalizado;
  }

  clientes.push({
    supabase_id: c.id,
    telefono: telefonoNormalizado,
    nombre: c.name || null,
    email: c.email || null,
    direccion: c.address || null,
    ciudad: c.city || 'Bogotá',
    total_pedidos: c.total_orders || 0,
    total_spent: c.total_spent || 0,
    is_active: c.is_active !== false,
    synced_at: new Date().toISOString()
  });
}

return [{ json: { mensaje: `${clientes.length} clientes listos para sincronizar (Parte 2)` }, clientes }];

// Recuperar clientes y generar UPSERTs
const inputData = $input.first().json;
const clientes = inputData.clientes || [];

if (clientes.length === 0) {
  return [{ json: { mensaje: 'No hay clientes para sincronizar en Parte 2', total: 0 } }];
}

return clientes.map(c => ({ json: c }));
